import "../../styles/canteen-ui.css";

export default function PaymentModal({ total, onCancel, onSuccess }) {
  return (
    <div className="payment-overlay">
      <div className="payment-box">
        <h3>Demo Payment</h3>

        <p>Total Amount: ₹{total}</p>

        <div className="payment-methods">
          <button onClick={onSuccess}>Pay with UPI (Demo)</button>
          <button onClick={onSuccess}>Pay with Card (Demo)</button>
          <button onClick={onSuccess}>Cash on Delivery (Demo)</button>
        </div>

        <button className="cancel-btn" onClick={onCancel}>
          Cancel
        </button>
      </div>
    </div>
  );
}
